/**
 * Word data for A Little Word Break. Loaded lazily (dynamic import) the first time the game opens,
 * so none of it ships with the regular page bundle.
 *
 * - VALID: every accepted guess — SCOWL (wordlist-english, sizes 10–70; English/American/British)
 *   merged with word-list@4.1.0, five-letter lowercase words only.
 * - ANSWERS: common words only (SCOWL sizes 10–35), minus plurals, past tenses and anything unkind,
 *   shuffled once with a fixed seed. The order IS the schedule: never re-sort or edit in place —
 *   append new words to the end instead, or every past and future day shifts.
 *
 * Both are packed as one continuous string (5 letters per word) to keep the chunk small.
 */
export const ANSWERS = "";

export const VALID = "";
